 while (a != NULL && b != NULL)
 {
 if (a->data != b ->data)
 return false; 
 /* If we reach here, then a and b are not NULL and their data is same, so 
move to next nodes in both lists */
 a = a->next;
 b = b->next;
 } 
 //If linked lists are identical, then 'a' and 'b' must be NULL at this point.
 return (a == NULL && b == NULL);
}
