 if (*head_ref == NULL || (* head_ref )->data >= new_node ->data)
 {
 new_node ->next = * head_ref ;
 *head_ref = new_node ;
 }
 else
 {
 /* Locate the node before the point of insertion */
 current = * head_ref ;
 while (current ->next!=NULL && current ->next->data < new_node ->data)
 {
 current = current ->next;
 }
