class HashTable:
def __init__(self, size=11): self.size=size; self.table=[[] for _ in range(size)]; self.count=0
def _hash(self, k): return hash(k) % self.size
def insert(self, k, v):
if self.count/self.size >= 0.7: self._resize() # Auto -resize at 70% load
idx = self._hash(k)
for i,(ek,ev) in enumerate(self.table[idx]):
if ek==k: self.table[idx][i]=(k,v); return # Update existing
self.table[idx].append((k,v)); self.count+=1
def _resize(self): # Double size, rehash all
old=self.table; self.size*=2; self.table=[[] for _ in range(self.size)]; self.count=0
for bucket in old:
for k,v in bucket: self.insert(k,v)
def get(self, k): return next((v for ek,v in self.table[self._hash(k)] if ek==k), None)
